#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
typedef struct {char*name;int w,d,l;} team;static char*copy(const char*s){char*r=(char*)malloc(strlen(s)+1);strcpy(r,s);return r;}static size_t lookup(team**t,size_t*n,const char*s){for(size_t i=0;i<*n;i++)if(!strcmp((*t)[i].name,s))return i;*t=(team*)realloc(*t,(*n+1)*sizeof(team));team v={copy(s),0,0,0};(*t)[*n]=v;return (*n)++;}char*tally(const char*const*g,size_t n){team*t=NULL;size_t count=0;for(size_t i=0;i<n;i++){char*s=copy(g[i]),*a=strchr(s,';');if(!a){free(s);continue;}*a++=0;char*b=strchr(a,';');if(!b){free(s);continue;}*b++=0;if(strcmp(b,"win")&&strcmp(b,"loss")&&strcmp(b,"draw")){free(s);continue;}size_t x=lookup(&t,&count,s),y=lookup(&t,&count,a);if(!strcmp(b,"draw")){t[x].d++;t[y].d++;}else if(!strcmp(b,"win")){t[x].w++;t[y].l++;}else{t[x].l++;t[y].w++;}free(s);}for(size_t i=0;i<count;i++)for(size_t j=i+1;j<count;j++){int a=3*t[i].w+t[i].d,b=3*t[j].w+t[j].d;if(b>a||(a==b&&strcmp(t[j].name,t[i].name)<0)){team tmp=t[i];t[i]=t[j];t[j]=tmp;}}size_t cap=100;for(size_t i=0;i<count;i++)cap+=strlen(t[i].name)+100;char*out=(char*)malloc(cap);strcpy(out,"Team                           | MP |  W |  D |  L |  P");for(size_t i=0;i<count;i++){sprintf(out+strlen(out),"\n%-30s | %2d | %2d | %2d | %2d | %2d",t[i].name,t[i].w+t[i].d+t[i].l,t[i].w,t[i].d,t[i].l,3*t[i].w+t[i].d);free(t[i].name);}free(t);return out;}

